-- Run admission with staged output. A fan-out join carries a leg outcome only up to the kernel bound (16 KB), so the
-- execute leg stages the capability output in the run store (evidence.stage_run_output, sfx-identity migration 007) and
-- settles its digest; the join completes the run from the staged output (evidence.complete_staged_run). The carry leg
-- carries only the run id, admission time and capability. The answer stage unwraps an object value as well as text.
-- Revises three transformations of 05 by their current digests, adds two, and re-applies the capability. One transaction.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lk int;
EXEC @lk = sys.sp_getapplock @Resource = N'sidefx:model-write', @LockMode = N'Update', @LockOwner = N'Transaction', @LockTimeout = 30000;
IF @lk < 0 THROW 51000, N'MODEL_WRITE_LOCK_UNAVAILABLE', 1;

