EXEC model.apply_capability_from_dsl @document = N'{"contractId":"capability-from-dsl-change.v1","source":"capability admit-api-run\nintent: Admit a run of a declared capability through the declared API: the run store of the sfx-identity database registers it under the caller session and mints its run id, the kernel runs the capability and stages its output by digest, and the store completes the run from the staged output; a carry leg brings the run id to the completion, because a join carries a leg outcome only up to the kernel bound.\noutcome: status COMPLETED with the run id and its state; a refused registration answers its refusal\ninquiry: Which run did this admission create?\ninput contract admit-api-run.v1 {\"type\":[\"object\",\"array\"]}\noutput contract admit-api-run.v1 {\"type\":[\"object\",\"array\"]}\ncli display outcome as json\nscenario admit-api-run root\ngiven: an admission (object, operation, subject, namespace, input) with the caller principal and session\nwhen: the run store registers the run\nthen: the run id and the admission go to both legs\noperation admit-api-run.prepare kind invoke-port port admit-api-run-prepare\noperation admit-api-run.register kind invoke-port port admit-api-run-register\noperation admit-api-run.lift kind invoke-port port admit-api-run-lift\nplatform bind admit-api-run-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-prepare\"}\nplatform bind admit-api-run-register\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"sql-database-reader\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind admit-api-run-lift\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-lift\"}\nscenario admit-api-run-execute\ngiven: the registered run and its admission\nwhen: the kernel runs the admitted capability and the run store stages its output\nthen: the output digest settles the execute slot\noperation admit-api-run-execute.prepare kind invoke-port port admit-api-run-execute-prepare\noperation admit-api-run-execute.run kind invoke-port port admit-api-run-execute-run\noperation admit-api-run-execute.stage kind invoke-port port admit-api-run-execute-stage\noperation admit-api-run-execute.store kind invoke-port port admit-api-run-execute-store\noperation admit-api-run-execute.lift kind invoke-port port admit-api-run-execute-lift\nplatform bind admit-api-run-execute-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-execute-prepare\"}\nplatform bind admit-api-run-execute-run\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"generic-capability-invocation\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind admit-api-run-execute-stage\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-execute-stage\"}\nplatform bind admit-api-run-execute-store\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"generic-capability-invocation\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind admit-api-run-execute-lift\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-execute-lift\"}\nscenario admit-api-run-carry\ngiven: the registered run\nwhen: the run id is carried\nthen: it settles the carry slot\noperation admit-api-run-carry.carry kind invoke-port port admit-api-run-carry\nplatform bind admit-api-run-carry\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-carry\"}\nscenario admit-api-run-complete\ngiven: the execute and carry slots\nwhen: the run store completes the run from its staged output\nthen: the outcome is the completed run\noperation admit-api-run-complete.prepare kind invoke-port port admit-api-run-complete-prepare\noperation admit-api-run-complete.complete kind invoke-port port admit-api-run-complete-complete\noperation admit-api-run-complete.answer kind invoke-port port admit-api-run-answer\nplatform bind admit-api-run-complete-prepare\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-complete-prepare\"}\nplatform bind admit-api-run-complete-complete\nplatform: generic-capability-invocation.v1\nconfig: {\"providerId\":\"generic-capability-invocation\",\"authoritySource\":\"DATABASE\",\"capabilityIdPath\":\"executionTarget\",\"namespacePath\":\"executionNamespace\",\"scenarioPath\":\"executionScenario\",\"requestPath\":\"dispatchRequest\",\"resultPath\":\"result\",\"lineageMode\":\"retain-nested-execution\"}\nplatform bind admit-api-run-answer\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"admit-api-run-answer\"}\nbroadcast admit-api-run to admit-api-run-execute,admit-api-run-carry\njoin admit-api-run-complete from admit-api-run-execute,admit-api-run-carry","isMcpTooling":false}';

